public class ReferenceListingHoverPlugin : Plugin {

	private ReferenceListingHover referenceHoverService;

	public ReferenceListingHoverPlugin(PluginTool tool) : base(tool)
    {
		referenceHoverService = new ReferenceListingHover(tool);
		registerServiceProvided(typeof(ListingHoverService), referenceHoverService);
	}

	/* @Override */
	public void init() {
		// The ReferenceHover is dependent on the CodeFormatService.
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		if (@event is ProgramClosedPluginEvent) {
			ProgramClosedPluginEvent ev = (ProgramClosedPluginEvent) @event;
			referenceHoverService.programClosed(ev.getProgram());
		}
	}

	/* @Override */
	public void dispose() {
		referenceHoverService.dispose();
	}

	/* testing */
	public ReferenceListingHover getReferenceHoverService() {
		return referenceHoverService;
	}
}
